B.alA=new A.c7("Ch\u01b0a c\xf3 y\xeau c\u1ea7u thanh to\xe1n.",B.a3,null)
B.alB=new A.c7("Ch\u1ec9 chia s\u1ebb m\xe3 v\u1edbi ng\u01b0\u1eddi c\xf9ng nh\xf3m. T\u1ea1o m\xe3 m\u1edbi s\u1ebd thay th\u1ebf m\xe3 c\u0169; th\xe0nh vi\xean nh\u1eadp m\xe3 trong m\u1ee5c D\u1ecbch v\u1ee5 c\u1ee7a t\xf4i.",B.a3,null)
