B.alG=new A.c7("H\u1ecfi v\u1ec1 hi\u1ec7n v\u1eadt \u0111ang xem. Tr\u1ee3 l\xfd tham kh\u1ea3o n\u1ed9i dung ti\u1ebfng Vi\u1ec7t \u0111\xe3 \u0111\u01b0\u1ee3c b\u1ea3o t\xe0ng xu\u1ea5t b\u1ea3n.",B.a3,null)
B.alH=new A.c7("Ch\u01b0a c\xf3 n\u1ed9i dung c\u1ee7a g\xf3i.",B.a3,null)
B.alI=new A.c7("M\u1edf \u1ee9ng d\u1ee5ng ng\xe2n h\xe0ng b\u1ea5t k\u1ef3 \u0111\u1ec3 qu\xe9t m\xe3 QR, ho\u1eb7c sao ch\xe9p ch\xednh x\xe1c s\u1ed1 t\xe0i kho\u1ea3n v\xe0 n\u1ed9i dung chuy\u1ec3n kho\u1ea3n tr\xean.",B.a3,null)
B.alJ=new A.c7("\u0110\xe1nh gi\xe1 b\u1ea3o t\xe0ng c\u1ea7n g\u1eafn v\u1edbi l\u01b0\u1ee3t tham quan \u0111\xe3 ho\xe0n th\xe0nh. G\xf3p \xfd chung s\u1ebd \u0111\u01b0\u1ee3c g\u1eedi \u0111\u1ebfn b\u1ed9 ph\u1eadn h\u1ed7 tr\u1ee3.",B.a3,null)
